messages.content:
Game arcade "Pasar Pagi Sprint" siap dimainkan: lari di pasar pagi yang padat, ambil koin, dan lompati keranjang, kardus, serta genangan. Saya memakai tingkat Menantang (3 nyawa) dan preset Retro Pixel sesuai blueprint.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "pasar-pagi-sprint", title: "Pasar Pagi Sprint", seed: "pasar-pagi-01",
  theme: { preset: "retro-pixel" },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 420, maxSpeed: 720, accel: 10 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "keranjang", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "kardus",    w: 60, h: 70, weight: 2 },
      { type: "hazard", id: "genangan",  w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: false },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 12, speed: 30 }
  }
});
// END_OF_MANIFEST
```
